args.CommandLine:
curl -sL "https://www.bbc.com/news" | python3 -c "
import sys, re, json
html = sys.stdin.read()
m = re.search(r'<script id=\"__NEXT_DATA__\" type=\"application/json\">(.*?)</script>', html)
if m:
    data = json.loads(m.group(1))
    # find headlines
    text = json.dumps(data)
    for h in re.findall(r'\"headline\":\"([^\"]+)\"', text)[:10]:
        print('HEADLINE:', h)
    for t in re.findall(r'\"title\":\"([^\"]+)\"', text)[:15]:
        print('TITLE:', t)
else:
    for h in re.findall(r'<h[123][^>]*>(.*?)</h[123]>', html, re.S)[:15]:
        clean = re.sub(r'<[^>]+>', '', h).strip()
        if clean:
            print('H:', clean)
"
